import { ChakraProvider } from "@chakra-ui/react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";
import type { Proposal, Ticket, TicketStatusOption } from "@/features/projects/types";
import psTheme from "@/theme/theme";
import { KanbanBoard } from "./kanban-board";

const ticket = (overrides: Partial<Ticket> = {}): Ticket => ({
  id: "ticket-1",
  shorthand: "TK0001",
  title: "Draft proposal",
  content: "Draft the initial proposal outline.",
  tagIds: [],
  status: "backlog",
  assignee: "Nina",
  updatedAt: "2026-02-01",
  ...overrides,
});

const columns: TicketStatusOption[] = ["backlog", "ready", "wip", "in Review", "Done", "Canceled"].map(
  (name, index) => ({
    id: `status-${index}`,
    name,
    color: "gray",
    sortOrder: index + 1,
    isDefault: index === 0,
    canDragOut: name !== "wip",
    canDragIn: true,
    canCreate: name === "backlog",
    canAttemptOnDrop: name === "wip",
  }),
);

const renderBoard = (tickets: Ticket[], proposals: Proposal[] = [], selectedTicketId: string | null = null) =>
  renderToStaticMarkup(
    <ChakraProvider value={psTheme}>
      <KanbanBoard
        tickets={tickets}
        columns={columns}
        proposals={proposals}
        onCreateTicket={() => {}}
        selectedTicketId={selectedTicketId}
      />
    </ChakraProvider>,
  );

describe("KanbanBoard", () => {
  it("renders empty columns when there are no tickets", () => {
    const markup = renderBoard([]);

    expect(markup).toContain('data-testid="kanban-board"');
    expect(markup).toContain("backlog");
    expect(markup).toContain("ready");
    expect(markup).toContain("0 tickets");
    expect(markup).not.toContain("No tickets yet");
  });

  it("keeps columns in a single horizontal row", () => {
    const markup = renderBoard([ticket()]);

    expect(markup).toContain('data-testid="kanban-board"');
    expect(markup).toContain('data-layout="row"');
  });

  it("renders independently scrollable ticket areas per column", () => {
    const markup = renderBoard([ticket()]);
    const occurrences = markup.split('data-testid="kanban-column-tickets"').length - 1;

    expect(occurrences).toBe(columns.length);
  });

  it("shows the proposal title tag for proposal tickets", () => {
    const markup = renderBoard(
      [ticket({ proposalId: "proposal-1" })],
      [
        {
          id: "proposal-1",
          shorthand: "C0001_improve-onboarding",
          title: "Improve onboarding",
          summary: "Tighten the onboarding flow.",
          description: "Expand onboarding checklists.",
          status: "wip",
          updatedAt: "2026-02-02",
          ticketIds: ["ticket-1"],
        },
      ],
    );

    expect(markup).toContain("Expand onboarding checklists.");
    expect(markup).not.toContain("Updated");
  });

  it("shows create ticket buttons only on creatable columns", () => {
    const markup = renderBoard([]);
    const occurrences = markup.split('aria-label="Create ticket"').length - 1;

    expect(occurrences).toBe(columns.filter((column) => column.canCreate).length);
  });

  it("marks the selected ticket card", () => {
    const markup = renderBoard([ticket({ id: "ticket-1" })], [], "ticket-1");

    expect(markup).toContain('data-selected="true"');
  });

  it("disables dragging for columns that cannot drag out", () => {
    const markup = renderBoard([ticket({ status: "wip" })]);

    expect(markup).toContain('draggable="false"');
  });

  it("shows an empty ticket label when the ticket description is empty", () => {
    const markup = renderBoard([
      ticket({
        title: "TK0099",
        content: "   ",
      }),
    ]);

    expect(markup).toContain("empty ticket");
    expect(markup).not.toContain("TK0099");
  });
});

