import { Badge, Button, HStack, Icon, IconButton, Input, Menu, Spacer, Stack, Text } from "@chakra-ui/react";
import { Plus } from "lucide-react";
import { type DragEvent, type KeyboardEvent, useState } from "react";
import { Tooltip } from "@/components/tooltip";
import type { Proposal, Ticket, TicketStatus, TicketStatusOption } from "@/features/projects/types";
import { formatProposalTitle } from "@/features/proposals/utils";
import { logMutationError } from "@/lib/error-handlers";
import { buildCreateTicketPayload, buildKanbanColumns, type CreateTicketPayload } from "../utils/kanban-utils";
import { KanbanCard } from "./kanban-card";

interface KanbanBoardProps {
  tickets: Ticket[];
  columns: TicketStatusOption[];
  proposals?: Proposal[];
  onMoveTicket?: (ticketId: string, nextStatus: TicketStatus) => void;
  onSelectTicket?: (ticket: Ticket) => void;
  onCreateTicket?: (status: TicketStatus, payload: CreateTicketPayload) => Promise<void> | void;
  isCreatingTicket?: boolean;
  selectedTicketId?: string | null;
}

export const KanbanBoard = (props: KanbanBoardProps) => {
  const {
    tickets,
    columns: statusColumns,
    proposals = [],
    onMoveTicket,
    onSelectTicket,
    onCreateTicket,
    isCreatingTicket = false,
    selectedTicketId = null,
  } = props;
  const columns = buildKanbanColumns(tickets, statusColumns);
  const [activeColumn, setActiveColumn] = useState<TicketStatus | null>(null);
  const [createColumn, setCreateColumn] = useState<TicketStatus | null>(null);
  const [createContent, setCreateContent] = useState("");
  const [createComplexity, setCreateComplexity] = useState<"low" | "medium" | "high">("medium");
  const proposalTitles = new Map(proposals.map((proposal) => [proposal.id, formatProposalTitle(proposal)]));

  const handleDragStart = (ticket: Ticket) => (event: DragEvent<HTMLDivElement>) => {
    event.dataTransfer.setData("text/plain", ticket.id);
    event.dataTransfer.setData("application/x-kanban-status", ticket.status);
    event.dataTransfer.effectAllowed = "move";
  };

  const handleDragEnd = () => {
    setActiveColumn(null);
  };

  const handleDragOver = (status: TicketStatus) => (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    setActiveColumn(status);
  };

  const handleDrop = (status: TicketStatus) => (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setActiveColumn(null);

    const ticketId = event.dataTransfer.getData("text/plain");
    const currentStatus = event.dataTransfer.getData("application/x-kanban-status") as TicketStatus;

    if (!ticketId || currentStatus === status) return;

    onMoveTicket?.(ticketId, status);
  };

  const handleCreateStart = (status: TicketStatus) => {
    setCreateColumn(status);
    setCreateContent("");
    setCreateComplexity("medium");
  };

  const handleCreateCancel = () => {
    setCreateColumn(null);
    setCreateContent("");
    setCreateComplexity("medium");
  };

  const handleCreateSubmit = async (status: TicketStatus) => {
    const payload = buildCreateTicketPayload(createContent, createComplexity);
    if (!payload.title || !onCreateTicket) {
      return;
    }

    try {
      await onCreateTicket(status, payload);
      handleCreateCancel();
    } catch (error) {
      logMutationError("create ticket", error);
    }
  };

  const handleCreateKeyDown = (status: TicketStatus) => (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter") {
      event.preventDefault();
      handleCreateSubmit(status);
    }

    if (event.key === "Escape") {
      event.preventDefault();
      handleCreateCancel();
    }
  };

  return (
    <Stack
      height="100%"
      direction="row"
      gap="2xs"
      align="stretch"
      overflowX="auto"
      overflowY="hidden"
      paddingBottom="2xs"
      data-testid="kanban-board"
      data-layout="row"
    >
      {columns.map((column) => (
        <Stack
          key={column.id}
          gap="xs"
          padding="xs"
          _notFirst={{
            borderLeft: "1px solid",
            borderColor: "border",
          }}
          background={activeColumn === column.id ? "background.secondary" : "background.primary"}
          height="100%"
          minH="240px"
          overflow="hidden"
          minW="260px"
          flex="1 0 260px"
          onDragOver={column.canDragIn ? handleDragOver(column.id) : undefined}
          onDrop={column.canDragIn ? handleDrop(column.id) : undefined}
        >
          <HStack gap="xs" alignItems="center">
            <Text textStyle="label/L/medium">{column.label}</Text>
            <Badge variant="subtle" colorPalette="gray">
              {column.tickets.length} tickets
            </Badge>
            <Spacer />
            {column.canCreate && (
              <Tooltip content="Create new ticket">
                <IconButton
                  size="2xs"
                  variant="outline"
                  onClick={() => handleCreateStart(column.id)}
                  aria-label="Create ticket"
                  disabled={isCreatingTicket}
                >
                  <Icon as={Plus} boxSize="12px" />
                </IconButton>
              </Tooltip>
            )}
          </HStack>
          {onCreateTicket && column.canCreate ? (
            createColumn === column.id ? (
              <Stack gap="xs">
                <Input
                  size="sm"
                  placeholder="Ticket content"
                  value={createContent}
                  onChange={(event) => setCreateContent(event.target.value)}
                  onKeyDown={handleCreateKeyDown(column.id)}
                  disabled={isCreatingTicket}
                />
                <Menu.Root size="sm">
                  <Menu.Field
                    value={createComplexity}
                    onChange={(event) => setCreateComplexity(event.target.value as "low" | "medium" | "high")}
                    _disabled={{ opacity: 0.5, cursor: "not-allowed" }}
                  >
                    <option value="low">Low complexity</option>
                    <option value="medium">Medium complexity</option>
                    <option value="high">High complexity</option>
                  </Menu.Field>
                  <Menu.Indicator />
                </Menu.Root>
                <HStack gap="xs">
                  <Button
                    size="xs"
                    variant="solid"
                    onClick={() => handleCreateSubmit(column.id)}
                    loading={isCreatingTicket}
                    disabled={isCreatingTicket || !createContent.trim()}
                  >
                    Create
                  </Button>
                  <Button size="xs" variant="ghost" onClick={handleCreateCancel} disabled={isCreatingTicket}>
                    Cancel
                  </Button>
                </HStack>
              </Stack>
            ) : null
          ) : null}
          <Stack gap="sm" flex="1" minH="0" overflowY="auto" data-testid="kanban-column-tickets">
            {column.tickets.map((ticket) => (
              <KanbanCard
                key={ticket.id}
                ticket={ticket}
                proposalTitle={ticket.proposalId ? (proposalTitles.get(ticket.proposalId) ?? null) : null}
                isSelected={ticket.id === selectedTicketId}
                draggable={column.canDragOut}
                onDragStart={column.canDragOut ? handleDragStart(ticket) : undefined}
                onDragEnd={column.canDragOut ? handleDragEnd : undefined}
                onClick={() => onSelectTicket?.(ticket)}
              />
            ))}
          </Stack>
        </Stack>
      ))}
    </Stack>
  );
};

