import { ChakraProvider } from "@chakra-ui/react";
import { renderToStaticMarkup } from "react-dom/server";
import { beforeEach, describe, expect, it, vi } from "vitest";

import psTheme from "@/theme/theme";
import { ThemePreferenceProvider } from "@/theme/theme-preference";
import { ProjectBoard } from "./project-board";

const updateTicketStatusMutate = vi.fn();
const createAttemptMutate = vi.fn();
const createTicketMutate = vi.fn();
const openTicketMock = vi.fn();

const projectMock = vi.fn();
const ticketsMock = vi.fn();
let moveStatus = "wip";

vi.mock("@tanstack/react-router", () => ({
  useParams: () => ({ projectId: "project-1" }),
}));

vi.mock("@/features/projects/hooks/use-project", async () => {
  const actual = await vi.importActual<typeof import("@/features/projects/hooks/use-project")>(
    "@/features/projects/hooks/use-project",
  );

  return {
    ...actual,
    useProject: () => projectMock(),
    useProjectTickets: () => ticketsMock(),
    useUpdateProjectTicketStatus: () => ({ mutateAsync: updateTicketStatusMutate }),
  };
});

vi.mock("@/features/tickets/hooks/use-create-ticket-attempt", () => ({
