import { Stack, Text } from "@chakra-ui/react";
import { useParams } from "@tanstack/react-router";
import { getStoredAgent } from "@/features/onboarding/agent-storage";
import { useProject, useProjectTickets, useUpdateProjectTicketStatus } from "@/features/projects/hooks/use-project";
import type { TicketStatus } from "@/features/projects/types";
import { useCreateProjectTicket } from "@/features/tickets/hooks/use-create-project-ticket";
import { useCreateTicketAttempt } from "@/features/tickets/hooks/use-create-ticket-attempt";
import { useTicketPanel } from "@/features/tickets/hooks/use-ticket-panel";
import { logMutationError } from "@/lib/error-handlers";
import { KanbanBoard } from "../components/kanban-board";
import type { CreateTicketPayload } from "../utils/kanban-utils";

export const ProjectBoard = () => {
  const { projectId } = useParams({ strict: false });
  const { data: project, isLoading: isProjectLoading } = useProject(projectId);
  const { data: tickets, isLoading: isTicketsLoading } = useProjectTickets(projectId);
  const updateTicketStatus = useUpdateProjectTicketStatus(projectId);
  const createTicket = useCreateProjectTicket(projectId);
  const createAttempt = useCreateTicketAttempt(projectId);
  const { ticket, openTicket } = useTicketPanel();
  const isLoading = isProjectLoading || isTicketsLoading;
  const columns = project?.ticketStatusOptions ?? [];
  const selectedTicketId = ticket?.id ?? null;

  const isWipStatus = (value: string) => {
    const normalized = value.trim().toLowerCase();
    return normalized.includes("wip") || normalized.includes("progress");
  };

  const handleMoveTicket = (ticketId: string, status: TicketStatus) => {
    const targetStatus = columns.find((column) => column.id === status || column.name === status);
    const resolvedStatus = targetStatus?.name ?? status;
    const ticket = (tickets ?? []).find((item) => item.id === ticketId);
    const repoId = project?.repositories[0]?.id ?? null;
    const promptSource = ticket?.content?.trim() ?? "";
    const prompt = promptSource.length > 0 ? promptSource : (ticket?.title ?? "");
    const shouldCreateAttempt = Boolean(targetStatus?.canAttemptOnDrop) || isWipStatus(resolvedStatus);

    updateTicketStatus
      .mutateAsync({ ticketId, status: resolvedStatus })
      .then(async () => {
        if (!shouldCreateAttempt) {
          return;
        }
        await createAttempt.mutateAsync({
          ticketId,
          agent: getStoredAgent() ?? "opencode",
          repoId,
          prompt: prompt.length > 0 ? prompt : null,
        });
      })
      .catch((error) => {
        logMutationError("move ticket", error);
      });
  };

  const handleCreateTicket = async (status: TicketStatus, payload: CreateTicketPayload) => {
    if (createTicket.isPending) {
      return;
    }

    try {
      const ticket = await createTicket.mutateAsync({
        title: payload.title,
        content: payload.content,
        complexity: payload.complexity,
        status,
      });
      openTicket(ticket);
    } catch (error) {
      logMutationError("create ticket", error);
    }
  };

  return (
    <Stack gap="lg" height={"100%"}>
      {isLoading ? (
        <Text textStyle="paragraph/S/regular" color="foreground.secondary">
          Loading tickets...
        </Text>
      ) : (
        <KanbanBoard
          tickets={tickets ?? []}
          columns={columns}
          proposals={project?.proposals ?? []}
          onMoveTicket={handleMoveTicket}
          onCreateTicket={handleCreateTicket}
          isCreatingTicket={createTicket.isPending}
          onSelectTicket={(ticket) => openTicket(ticket)}
          selectedTicketId={selectedTicketId}
        />
      )}
    </Stack>
  );
};

