    const statuses: TicketStatusOption[] = ["backlog", "ready", "wip", "in Review", "Done", "Canceled"].map(
      (name, index) => ({
        id: `status-${index}`,
        name,
        color: "gray",
        sortOrder: index + 1,
        isDefault: index === 0,
        canDragOut: name !== "wip",
        canDragIn: true,
        canCreate: name === "backlog",
        canAttemptOnDrop: name === "wip",
      }),
    );
    const tickets = [
