      ticket({ id: "t-2", status: "wip" }),
      ticket({ id: "t-3", status: "in Review" }),
      ticket({ id: "t-4", status: "Done" }),
      ticket({ id: "t-5", status: "backlog" }),
    ];

    const columns = buildKanbanColumns(tickets, statuses);

    expect(columns.map((column) => column.id)).toEqual(statuses.map((status) => status.name));
    expect(columns.find((column) => column.id === "backlog")?.tickets.map((item) => item.id)).toEqual(["t-1", "t-5"]);
    expect(columns.find((column) => column.id === "wip")?.tickets.map((item) => item.id)).toEqual(["t-2"]);
    expect(columns.find((column) => column.id === "in Review")?.tickets.map((item) => item.id)).toEqual(["t-3"]);
    expect(columns.find((column) => column.id === "Done")?.tickets.map((item) => item.id)).toEqual(["t-4"]);
    expect(columns.find((column) => column.id === "wip")?.canDragOut).toBe(false);
    expect(columns.find((column) => column.id === "backlog")?.canCreate).toBe(true);
  });

  it("pretty prints underscore statuses in column labels", () => {
    const statuses: TicketStatusOption[] = [
      {
        id: "status-1",
        name: "in_review",
        color: "purple",
        sortOrder: 1,
        isDefault: false,
        canDragOut: true,
        canDragIn: true,
        canCreate: false,
        canAttemptOnDrop: false,
      },
    ];

    const columns = buildKanbanColumns([ticket({ id: "t-1", status: "in_review" })], statuses);

    expect(columns[0]?.id).toBe("in_review");
    expect(columns[0]?.label).toBe("in review");
    expect(columns[0]?.tickets.map((item) => item.id)).toEqual(["t-1"]);
  });
});

describe("buildCreateTicketPayload", () => {
  it("derives the title from trimmed content while preserving the content", () => {
    const payload = buildCreateTicketPayload("  Draft the kickoff plan.  ");

    expect(payload).toEqual({
      title: "Draft the kickoff plan.",
      content: "  Draft the kickoff plan.  ",
      complexity: null,
    });
  });
});

describe("moveTicket", () => {
  it("updates the ticket status without altering other tickets", () => {
    const tickets = [ticket({ id: "t-1", status: "backlog" }), ticket({ id: "t-2", status: "in Review" })];

    const updated = moveTicket(tickets, "t-1", "Done");

    expect(updated.find((item) => item.id === "t-1")?.status).toBe("Done");
    expect(updated.find((item) => item.id === "t-2")?.status).toBe("in Review");
  });
});

