import { Badge, Box, Button, Icon as ChakraIcon, HStack, IconButton, Input, Stack, Text } from "@chakra-ui/react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Plus, Trash2 } from "lucide-react";
import { useEffect, useState } from "react";
import { projectKeys } from "@/features/projects/hooks/keys";
import { useProjectTicketStatuses } from "@/features/projects/hooks/use-project";
import type { TicketStatusColor, TicketStatusOption } from "@/features/projects/types";
import {
  createProjectTicketStatus,
  deleteProjectTicketStatus,
  TICKET_STATUS_PALETTE,
  updateProjectTicketStatusDefinition,
} from "../data/api";
import { DEFAULT_CAPABILITIES, StatusCapabilities } from "./status-capabilities";
import { StatusColorMenu } from "./status-color-menu";
import { buildStatusDraft, isStatusDraftEqual, type StatusDraft } from "./status-draft";

interface ProjectStatusSettingsProps {
  projectId?: string;
}

export const ProjectStatusSettings = (props: ProjectStatusSettingsProps) => {
  const { projectId } = props;
  const queryClient = useQueryClient();
  const { data: statuses = [], isLoading } = useProjectTicketStatuses(projectId);
  const [drafts, setDrafts] = useState<Record<string, StatusDraft>>({});
  const [newName, setNewName] = useState("");
  const [newColor, setNewColor] = useState<TicketStatusColor>(TICKET_STATUS_PALETTE[0] ?? "gray");
  const [newCanDragOut, setNewCanDragOut] = useState(DEFAULT_CAPABILITIES.canDragOut);
  const [newCanDragIn, setNewCanDragIn] = useState(DEFAULT_CAPABILITIES.canDragIn);
  const [newCanCreate, setNewCanCreate] = useState(DEFAULT_CAPABILITIES.canCreate);
  const [newCanAttemptOnDrop, setNewCanAttemptOnDrop] = useState(DEFAULT_CAPABILITIES.canAttemptOnDrop);
  const [error, setError] = useState("");

  useEffect(() => {
    const nextDrafts: Record<string, StatusDraft> = {};
    statuses.forEach((status) => {
      nextDrafts[status.id] = {
        name: status.name,
        color: status.color,
        canDragOut: status.canDragOut,
        canDragIn: status.canDragIn,
        canCreate: status.canCreate,
        canAttemptOnDrop: status.canAttemptOnDrop,
      };
    });
    setDrafts(nextDrafts);
  }, [statuses]);

  const invalidate = () => {
    if (!projectId) return;
    queryClient.invalidateQueries({ queryKey: projectKeys.ticketStatuses(projectId) });
    queryClient.invalidateQueries({ queryKey: projectKeys.detail(projectId) });
    queryClient.invalidateQueries({ queryKey: projectKeys.tickets(projectId) });
  };

  const createStatus = useMutation({
    mutationFn: async (input: {
      name: string;
      color: TicketStatusColor;
      sortOrder: number;
      isDefault: boolean;
      canDragOut: boolean;
      canDragIn: boolean;
      canCreate: boolean;
      canAttemptOnDrop: boolean;
    }) => {
      if (!projectId) {
        throw new Error("Project id is required.");
      }
      return createProjectTicketStatus(
        projectId,
        {
          name: input.name,
          color: input.color,
          canDragOut: input.canDragOut,
          canDragIn: input.canDragIn,
          canCreate: input.canCreate,
          canAttemptOnDrop: input.canAttemptOnDrop,
        },
        input,
      );
    },
    onSuccess: () => {
      setNewName("");
      setNewColor(TICKET_STATUS_PALETTE[0] ?? "gray");
      setNewCanDragOut(DEFAULT_CAPABILITIES.canDragOut);
      setNewCanDragIn(DEFAULT_CAPABILITIES.canDragIn);
      setNewCanCreate(DEFAULT_CAPABILITIES.canCreate);
      setNewCanAttemptOnDrop(DEFAULT_CAPABILITIES.canAttemptOnDrop);
      setError("");
      invalidate();
    },
    onError: (mutationError) => {
      const message = mutationError instanceof Error ? mutationError.message : "Unable to add status.";
      setError(message);
    },
  });

  const updateStatus = useMutation({
    mutationFn: async (input: {
      status: TicketStatusOption;
      name: string;
      color: TicketStatusColor;
      canDragOut: boolean;
      canDragIn: boolean;
      canCreate: boolean;
      canAttemptOnDrop: boolean;
    }) => {
      if (!projectId) {
        throw new Error("Project id is required.");
      }
      return updateProjectTicketStatusDefinition(projectId, input.status, {
        name: input.name,
        color: input.color,
        canDragOut: input.canDragOut,
        canDragIn: input.canDragIn,
        canCreate: input.canCreate,
        canAttemptOnDrop: input.canAttemptOnDrop,
      });
    },
    onSuccess: () => {
      setError("");
      invalidate();
    },
    onError: (mutationError) => {
      const message = mutationError instanceof Error ? mutationError.message : "Unable to update status.";
      setError(message);
    },
  });

  const deleteStatus = useMutation({
    mutationFn: async (statusId: string) => {
      if (!projectId) {
        throw new Error("Project id is required.");
      }
      await deleteProjectTicketStatus(projectId, statusId);
    },
    onSuccess: () => {
      setError("");
      invalidate();
    },
    onError: (mutationError) => {
      const message = mutationError instanceof Error ? mutationError.message : "Unable to remove status.";
      setError(message);
    },
  });

  const isWorking = createStatus.isPending || updateStatus.isPending || deleteStatus.isPending;
  const canRemove = statuses.length > 1;

  const handleDraftChange = (status: TicketStatusOption, patch: Partial<StatusDraft>) => {
    setDrafts((current) => ({
      ...current,
      [status.id]: buildStatusDraft(status, current[status.id], patch),
    }));
  };

  const handleUpdate = (status: TicketStatusOption, draft: StatusDraft) => {
    const trimmedName = draft.name.trim();
    if (!trimmedName) {
      setError("Status name is required.");
      handleDraftChange(status, { name: status.name });
      return;
    }

    const normalizedDraft = { ...draft, name: trimmedName };
    if (isStatusDraftEqual(status, normalizedDraft)) {
      return;
    }

    updateStatus.mutate({
      status,
      name: trimmedName,
      color: normalizedDraft.color,
      canDragOut: normalizedDraft.canDragOut,
      canDragIn: normalizedDraft.canDragIn,
      canCreate: normalizedDraft.canCreate,
      canAttemptOnDrop: normalizedDraft.canAttemptOnDrop,
    });
  };

  const handleAddStatus = () => {
    const trimmedName = newName.trim();
    if (!trimmedName) {
      setError("Status name is required.");
      return;
    }

    const maxSortOrder = statuses.reduce((max, status) => Math.max(max, status.sortOrder), 0);
    createStatus.mutate({
      name: trimmedName,
      color: newColor,
      sortOrder: maxSortOrder + 1,
      isDefault: statuses.length === 0,
      canDragOut: newCanDragOut,
      canDragIn: newCanDragIn,
      canCreate: newCanCreate,
      canAttemptOnDrop: newCanAttemptOnDrop,
    });
  };

  return (
    <Stack gap="sm" padding="md" borderWidth="1px" borderRadius="lg" borderColor="border.secondary">
      <Stack gap="xs">
        <Text textStyle="label/L/medium">Ticket statuses</Text>
        <Text textStyle="paragraph/S/regular" color="foreground.secondary">
          Edit kanban column labels and colors for this project.
        </Text>
      </Stack>

      {isLoading ? (
        <Text textStyle="paragraph/S/regular" color="foreground.secondary">
          Loading ticket statuses...
        </Text>
      ) : statuses.length === 0 ? (
        <Text textStyle="paragraph/S/regular" color="foreground.secondary">
          No statuses found.
        </Text>
      ) : (
        <Stack gap="xs">
          {statuses.map((status) => {
            const draft = buildStatusDraft(status, drafts[status.id]);
            return (
              <Stack key={status.id} gap="xs">
                <HStack gap="sm" align="center">
                  <Input
                    value={draft.name}
                    onChange={(event) => handleDraftChange(status, { name: event.target.value })}
                    onBlur={(event) => handleUpdate(status, { ...draft, name: event.target.value })}
                    disabled={isWorking}
                  />
                  <StatusColorMenu
                    value={draft.color}
                    onChange={(color) => {
                      const nextDraft = buildStatusDraft(status, draft, { color });
                      handleDraftChange(status, { color });
                      handleUpdate(status, nextDraft);
                    }}
                    disabled={isWorking}
                  />
                  {status.isDefault ? (
                    <Badge variant="subtle" colorPalette="green" textStyle="label/XS/medium">
                      Default
                    </Badge>
                  ) : null}
                  <IconButton
                    aria-label="Remove status"
                    size="xs"
                    variant="ghost"
                    disabled={!canRemove || isWorking}
                    onClick={() => deleteStatus.mutate(status.id)}
                  >
                    <ChakraIcon as={Trash2} boxSize="16px" />
                  </IconButton>
                </HStack>
                <StatusCapabilities
                  values={{
                    canDragOut: draft.canDragOut,
                    canDragIn: draft.canDragIn,
                    canCreate: draft.canCreate,
                    canAttemptOnDrop: draft.canAttemptOnDrop,
                  }}
                  onChange={(patch) => {
                    const nextDraft = buildStatusDraft(status, draft, patch);
                    handleDraftChange(status, patch);
                    handleUpdate(status, nextDraft);
                  }}
                  disabled={isWorking}
                />
              </Stack>
            );
          })}
        </Stack>
      )}

      <Box height="1px" background="border.secondary" />

      <Stack gap="xs">
        <Text textStyle="label/XS/regular" color="foreground.secondary">
          Add a new status
        </Text>
        <HStack gap="sm" align="center">
          <Input
            placeholder="Status name"
            value={newName}
            onChange={(event) => setNewName(event.target.value)}
            disabled={isWorking}
          />
          <StatusColorMenu value={newColor} onChange={setNewColor} disabled={isWorking} />
          <Button size="sm" variant="solid" onClick={handleAddStatus} disabled={isWorking}>
            <ChakraIcon as={Plus} boxSize="16px" mr="xs" />
            Add
          </Button>
        </HStack>
        <StatusCapabilities
          values={{
            canDragOut: newCanDragOut,
            canDragIn: newCanDragIn,
            canCreate: newCanCreate,
            canAttemptOnDrop: newCanAttemptOnDrop,
          }}
          onChange={(patch) => {
            if (patch.canDragOut !== undefined) {
              setNewCanDragOut(patch.canDragOut);
            }
            if (patch.canDragIn !== undefined) {
              setNewCanDragIn(patch.canDragIn);
            }
            if (patch.canCreate !== undefined) {
              setNewCanCreate(patch.canCreate);
            }
            if (patch.canAttemptOnDrop !== undefined) {
              setNewCanAttemptOnDrop(patch.canAttemptOnDrop);
            }
          }}
          disabled={isWorking}
        />
      </Stack>

      {error ? (
        <Text textStyle="label/XS/regular" color="red.500">
          {error}
        </Text>
      ) : null}
      {!canRemove ? (
        <Text textStyle="label/XS/regular" color="foreground.secondary">
          At least one status is required.
        </Text>
      ) : null}
    </Stack>
  );
};

