import type { TicketStatusOption } from "@/features/projects/types";
import { buildStatusDraft, isStatusDraftEqual } from "./status-draft";

const baseStatus: TicketStatusOption = {
  id: "status-1",
  name: "Backlog",
  color: "gray",
  sortOrder: 1,
  isDefault: true,
  canDragOut: true,
  canDragIn: true,
  canCreate: true,
  canAttemptOnDrop: false,
};

describe("status draft", () => {
  it("falls back to status values", () => {
    expect(buildStatusDraft(baseStatus)).toEqual({
      name: "Backlog",
      color: "gray",
      canDragOut: true,
      canDragIn: true,
      canCreate: true,
      canAttemptOnDrop: false,
    });
  });

  it("merges patch over existing draft", () => {
    const draft = buildStatusDraft(baseStatus, {
      color: "blue",
      canDragOut: false,
    });

    const next = buildStatusDraft(baseStatus, draft, { canCreate: false });

    expect(next).toEqual({
      name: "Backlog",
      color: "blue",
      canDragOut: false,
      canDragIn: true,
      canCreate: false,
      canAttemptOnDrop: false,
    });
  });

  it("detects when a draft matches the status", () => {
    const matching = buildStatusDraft(baseStatus);
    const mismatched = buildStatusDraft(baseStatus, { canDragOut: false });

    expect(isStatusDraftEqual(baseStatus, matching)).toBe(true);
    expect(isStatusDraftEqual(baseStatus, mismatched)).toBe(false);
  });
});

