import type { TicketColumnAction, TicketStatusColor, TicketStatusOption } from "@/features/projects/types";
import type { StatusCapabilitiesValues } from "./status-capabilities";

export type StatusDraft = StatusCapabilitiesValues & {
  name: string;
  color: TicketStatusColor;
  columnActions: TicketColumnAction[];
};

export const buildStatusDraft = (
  status: TicketStatusOption,
  draft?: Partial<StatusDraft>,
  patch?: Partial<StatusDraft>,
): StatusDraft => ({
  name: patch?.name ?? draft?.name ?? status.name,
  color: patch?.color ?? draft?.color ?? status.color,
  canDragOut: patch?.canDragOut ?? draft?.canDragOut ?? status.canDragOut,
  canDragIn: patch?.canDragIn ?? draft?.canDragIn ?? status.canDragIn,
  canCreate: patch?.canCreate ?? draft?.canCreate ?? status.canCreate,
  canAttemptOnDrop: patch?.canAttemptOnDrop ?? draft?.canAttemptOnDrop ?? status.canAttemptOnDrop,
  columnActions: patch?.columnActions ?? draft?.columnActions ?? status.columnActions,
});

export const isStatusDraftEqual = (status: TicketStatusOption, draft: StatusDraft) =>
  draft.name === status.name &&
  draft.color === status.color &&
  draft.canDragOut === status.canDragOut &&
  draft.canDragIn === status.canDragIn &&
  draft.canCreate === status.canCreate &&
  draft.canAttemptOnDrop === status.canAttemptOnDrop &&
  draft.columnActions.join("|") === status.columnActions.join("|");

