} from "./types";

export const DEFAULT_OWNER = "Unassigned";
export const DEFAULT_PROJECT_STATUS = "active";
export const DEFAULT_STATUS_NAME = "Unassigned";
export const TICKET_STATUS_PALETTE: TicketStatusColor[] = [
  "gray",
  "blue",
  "cyan",
  "green",
  "yellow",
  "orange",
  "red",
  "purple",
  "pink",
];
export const DEFAULT_STATUS_COLOR: TicketStatusColor = "gray";

export const toProjectListItem = (project: ApiProject): ProjectListItem => ({
  id: project.id,
  name: project.name,
  createdAt: project.created_at,
  updatedAt: project.updated_at,
});

export const toProjectRepository = (repo: ApiRepo): ProjectRepository => ({
  id: repo.id,
  name: repo.name,
  displayName: repo.display_name,
  path: repo.path,
  createdAt: repo.created_at,
  updatedAt: repo.updated_at,
});

export const toProjectTemplateAsset = (asset: ApiProjectTemplateAsset): ProjectTemplateAsset => ({
  id: asset.id,
  projectId: asset.project_id ?? "",
  name: asset.name,
  templateType: asset.template_type as ProjectTemplateAssetType,
  content: asset.content,
  createdAt: asset.created_at,
  updatedAt: asset.updated_at,
});

export const toRepoBranch = (branch: ApiRepoBranch): RepoBranch => ({
  name: branch.name,
  isCurrent: branch.is_current,
  isRemote: branch.is_remote,
  lastCommitDate: branch.last_commit_date,
});

export const normalizeTicketStatusColor = (color: string | null | undefined): TicketStatusColor => {
  if (!color) return DEFAULT_STATUS_COLOR;
  if (TICKET_STATUS_PALETTE.includes(color as TicketStatusColor)) {
    return color as TicketStatusColor;
  }
  return DEFAULT_STATUS_COLOR;
};

export const buildSummary = (description: string | null | undefined) => {
  if (!description) return "";

  const lines = description
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);

  if (lines.length === 0) return "";

  const candidate = lines.find((line) => !line.startsWith("#")) ?? lines[0];
  return candidate
    .replace(/^#+\s*/, "")
    .replace(/^[-*]\s*/, "")
    .trim();
};

export const toTicketStatusOption = (status: ApiTicketStatus): TicketStatusOption => ({
  id: status.id,
  name: status.name,
  color: normalizeTicketStatusColor(status.color),
  sortOrder: status.sort_order,
  isDefault: status.is_default === 1,
  canDragOut: status.can_drag_out === 1,
  canDragIn: status.can_drag_in === 1,
  canCreate: status.can_create === 1,
  canAttemptOnDrop: status.can_attempt_on_drop === 1,
});

export const buildTicketStatusCatalog = (statuses: ApiTicketStatus[]) => {
  const sorted = [...statuses].sort((a, b) => a.sort_order - b.sort_order);
  const options = sorted.map(toTicketStatusOption);
  const defaultStatus = options.find((status) => status.isDefault) ?? options[0];
  const fallbackName = defaultStatus?.name ?? DEFAULT_STATUS_NAME;
  const fallbackColor = defaultStatus?.color ?? DEFAULT_STATUS_COLOR;

  return {
    names: options.length ? options.map((status) => status.name) : [fallbackName],
    statusById: new Map(options.map((status) => [status.id, status.name])),
    idByName: new Map(options.map((status) => [status.name, status.id])),
    colorById: new Map(options.map((status) => [status.id, status.color])),
    fallbackName,
    fallbackColor,
    options,
  };
};

export const resolveProposalStatus = (status: string): Proposal["status"] => {
  const normalized = status.toLowerCase();
  const valid: Proposal["status"][] = ["draft", "wip", "in-review", "accepted", "rejected", "done", "archived"];
  return valid.includes(normalized as Proposal["status"]) ? (normalized as Proposal["status"]) : "draft";
};

export const toTicketAttempt = (attempt: ApiTicketAttempt): TicketAttempt => ({
  id: attempt.id,
  label: attempt.label,
  sessionId: attempt.session_id,
