    agentSessionStatus: resolveAgentSessionStatus(session.agent_session_status, session.agent_session_id ?? null),
    branch: session.branch ?? null,
    repoId: session.repo_id ?? null,
    messages: Array.isArray(session.messages) ? session.messages : [],
  };

  if (session.ticket_shorthand !== undefined) {
    projectSession.ticketShorthand = session.ticket_shorthand;
  }

  if (session.attempt_number !== undefined) {
    projectSession.attemptNumber = session.attempt_number;
  }

  return projectSession;
