import { integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";

export const projects = sqliteTable("projects", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  created_at: text("created_at").notNull(),
  updated_at: text("updated_at").notNull(),
});

export const repos = sqliteTable("repos", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  display_name: text("display_name"),
  path: text("path").notNull(),
  created_at: text("created_at").notNull(),
  updated_at: text("updated_at").notNull(),
});

export const project_repos = sqliteTable("project_repos", {
  id: text("id").primaryKey(),
  project_id: text("project_id")
    .notNull()
    .references(() => projects.id, { onDelete: "cascade" }),
  repo_id: text("repo_id")
    .notNull()
    .references(() => repos.id, { onDelete: "cascade" }),
  created_at: text("created_at").notNull(),
});

export const ticket_statuses = sqliteTable("ticket_statuses", {
  id: text("id").primaryKey(),
  project_id: text("project_id")
    .notNull()
    .references(() => projects.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  color: text("color").notNull(),
  sort_order: integer("sort_order").notNull(),
  is_default: integer("is_default").notNull(),
  is_open: integer("is_open").notNull().default(1),
  can_drag_out: integer("can_drag_out").notNull(),
  can_drag_in: integer("can_drag_in").notNull(),
  can_create: integer("can_create").notNull(),
  can_attempt_on_drop: integer("can_attempt_on_drop").notNull(),
  created_at: text("created_at").notNull(),
  updated_at: text("updated_at").notNull(),
});

export const proposal_statuses = sqliteTable("proposal_statuses", {
  id: text("id").primaryKey(),
  project_id: text("project_id")
    .notNull()
    .references(() => projects.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  sort_order: integer("sort_order").notNull(),
  is_default: integer("is_default").notNull(),
  created_at: text("created_at").notNull(),
  updated_at: text("updated_at").notNull(),
});

export const proposals = sqliteTable(
  "proposals",
  {
    id: text("id").primaryKey(),
    shorthand: text("shorthand").notNull(),
    project_id: text("project_id")
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    repo_id: text("repo_id").references(() => repos.id, { onDelete: "set null" }),
    input: text("input"),
    status: text("status").notNull().default("draft"),
    archived: integer("archived").notNull().default(0),
    staged: integer("staged").notNull().default(0),
    created_at: text("created_at").notNull(),
    updated_at: text("updated_at").notNull(),
  },
  (table) => ({
    projectShorthandIdx: uniqueIndex("proposals_project_shorthand_idx").on(table.project_id, table.shorthand),
  }),
);

export const tickets = sqliteTable(
  "tickets",
  {
    id: text("id").primaryKey(),
    shorthand: text("shorthand").notNull(),
    project_id: text("project_id")
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    proposal_id: text("proposal_id").references(() => proposals.id, {
      onDelete: "set null",
    }),
    status_id: text("status_id").references(() => ticket_statuses.id, {
      onDelete: "set null",
    }),
    content: text("content"),
    input: text("input"),
    priority: text("priority"),
    parallelizable: text("parallelizable"),
    complexity: text("complexity"),
    blocked_by: text("blocked_by"),
    blocked_reason: text("blocked_reason"),
    dependencies: text("dependencies"),
    archived: integer("archived").notNull().default(0),
    staged: integer("staged").notNull().default(0),
    created_at: text("created_at").notNull(),
    updated_at: text("updated_at").notNull(),
  },
  (table) => ({
    projectShorthandIdx: uniqueIndex("tickets_project_shorthand_idx").on(table.project_id, table.shorthand),
  }),
);

export const ticket_tags = sqliteTable(
  "ticket_tags",
  {
    id: text("id").primaryKey(),
    project_id: text("project_id")
      .notNull()
      .references(() => projects.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    color: text("color").notNull(),
    created_at: text("created_at").notNull(),
    updated_at: text("updated_at").notNull(),
  },
  (table) => ({
    projectNameIdx: uniqueIndex("ticket_tags_project_name_idx").on(table.project_id, table.name),
  }),
);

export const ticket_tag_assignments = sqliteTable(
  "ticket_tag_assignments",
  {
    id: text("id").primaryKey(),
    ticket_id: text("ticket_id")
      .notNull()
      .references(() => tickets.id, { onDelete: "cascade" }),
    ticket_tag_id: text("ticket_tag_id")
      .notNull()
