import { expect, test } from "bun:test";
import { createDb } from "../db/connection";
import { createProjectsService } from "./projects";
import { createProposalStatusesService } from "./proposal-statuses";
import { createTicketStatusesService } from "./ticket-statuses";

test("projects service supports basic CRUD", () => {
  const { db } = createDb({ path: ":memory:" });
  const projects = createProjectsService(db);

  const created = projects.create({ name: "Alpha" });

  expect(typeof created.id).toBe("string");
  expect(created.name).toBe("Alpha");
  expect(created.created_at).toBeTruthy();
  expect(created.updated_at).toBeTruthy();

  const fetched = projects.get(created.id);
  expect(fetched).toEqual(created);

  const list = projects.list();
  expect(list).toHaveLength(1);

  const updated = projects.update(created.id, { name: "Beta" });
  expect(updated?.name).toBe("Beta");

  const removed = projects.remove(created.id);
  expect(removed).toBe(true);
  expect(projects.get(created.id)).toBeNull();
});

test("projects service seeds default ticket statuses", () => {
  const { db } = createDb({ path: ":memory:" });
  const projects = createProjectsService(db);
  const ticketStatuses = createTicketStatusesService(db);

  const created = projects.create({ name: "Alpha" });
  const statuses = ticketStatuses.list(created.id);

  expect(statuses.map((status) => status.name)).toEqual(["backlog", "ready", "wip", "blocked", "in_review", "done"]);
  expect(statuses.find((status) => status.is_default === 1)?.name).toBe("backlog");
  expect(statuses.find((status) => status.name === "backlog")?.can_create).toBe(1);
  expect(statuses.find((status) => status.name === "wip")?.can_drag_out).toBe(0);
  expect(statuses.find((status) => status.name === "wip")?.can_attempt_on_drop).toBe(1);
  expect(statuses.every((status) => status.can_drag_in === 1)).toBe(true);
});

test("projects service seeds default proposal statuses", () => {
  const { db } = createDb({ path: ":memory:" });
  const projects = createProjectsService(db);
  const proposalStatuses = createProposalStatusesService(db);

  const created = projects.create({ name: "Alpha" });
  const statuses = proposalStatuses.list(created.id);

  expect(statuses.map((status) => status.name)).toEqual([
    "draft",
    "pending review",
    "wip",
    "in-review",
    "accepted",
    "rejected",
    "done",
    "archived",
  ]);
  expect(statuses.find((status) => status.is_default === 1)?.name).toBe("draft");
});

test("projects service emits json patches for changes", () => {
  const { db } = createDb({ path: ":memory:" });
  const projects = createProjectsService(db);

  const patches: Array<
    Array<{
      op: string;
      path: string;
      value?: unknown;
    }>
  > = [];
  const unsubscribe = projects.subscribe((patch) => {
    patches.push(patch);
  });

  const created = projects.create({ name: "Alpha" });
  const updated = projects.update(created.id, { name: "Beta" });
  projects.remove(created.id);
  unsubscribe();

  expect(patches[0]).toEqual([{ op: "add", path: `/projects/${created.id}`, value: created }]);
  expect(patches[1]).toEqual([{ op: "replace", path: `/projects/${created.id}`, value: updated }]);
  expect(patches[2]).toEqual([{ op: "remove", path: `/projects/${created.id}` }]);
});

test("projects service exposes snapshot map keyed by id", () => {
  const { db } = createDb({ path: ":memory:" });
  const projects = createProjectsService(db);

  const first = projects.create({ name: "Alpha" });
  const second = projects.create({ name: "Beta" });

  const snapshot = projects.getSnapshot();

  expect(snapshot.projects[first.id]).toEqual(first);
  expect(snapshot.projects[second.id]).toEqual(second);
});

