import { eq } from "drizzle-orm";
import type { DbClient } from "../db/connection";
import { projects, proposal_statuses, ticket_statuses } from "../db/schema";

type ProjectRecord = typeof projects.$inferSelect;

export type JsonPatchOperation = {
  op: "add" | "replace" | "remove";
  path: string;
  value?: unknown;
};

export type ProjectsSnapshot = {
  projects: Record<string, ProjectRecord>;
};

const DEFAULT_TICKET_STATUSES = [
  {
    name: "backlog",
    color: "gray",
    is_default: 1,
    is_open: 1,
    can_drag_out: 1,
    can_drag_in: 1,
    can_create: 1,
    can_attempt_on_drop: 0,
  },
  {
    name: "ready",
    color: "blue",
    is_default: 0,
    is_open: 1,
    can_drag_out: 1,
    can_drag_in: 1,
    can_create: 0,
    can_attempt_on_drop: 0,
  },
  {
    name: "wip",
    color: "orange",
    is_default: 0,
    is_open: 1,
    can_drag_out: 0,
    can_drag_in: 1,
    can_create: 0,
    can_attempt_on_drop: 1,
  },
  {
    name: "blocked",
    color: "red",
    is_default: 0,
    is_open: 1,
    can_drag_out: 1,
    can_drag_in: 1,
    can_create: 0,
    can_attempt_on_drop: 0,
  },
  {
    name: "in_review",
    color: "purple",
    is_default: 0,
    is_open: 1,
    can_drag_out: 1,
    can_drag_in: 1,
    can_create: 0,
    can_attempt_on_drop: 0,
  },
  {
    name: "done",
    color: "green",
    is_default: 0,
    is_open: 0,
    can_drag_out: 1,
    can_drag_in: 1,
    can_create: 0,
    can_attempt_on_drop: 0,
  },
] as const;

const DEFAULT_PROPOSAL_STATUSES = [
  { name: "draft", is_default: 1 },
  { name: "pending review", is_default: 0 },
  { name: "wip", is_default: 0 },
  { name: "in-review", is_default: 0 },
  { name: "accepted", is_default: 0 },
  { name: "rejected", is_default: 0 },
  { name: "done", is_default: 0 },
  { name: "archived", is_default: 0 },
] as const;

const nowTimestamp = () => new Date().toISOString();

const encodeJsonPointerSegment = (value: string) => value.replace(/~/g, "~0").replace(/\//g, "~1");

export const createProjectsService = (db: DbClient) => {
  const listeners = new Set<(patches: JsonPatchOperation[]) => void>();

  const notify = (patches: JsonPatchOperation[]) => {
    listeners.forEach((listener) => {
      listener(patches);
    });
  };

  const list = () => db.select().from(projects).orderBy(projects.created_at).all();

  const get = (id: string) => {
    const project = db.select().from(projects).where(eq(projects.id, id)).get();
    return project ?? null;
  };

  const getSnapshot = (): ProjectsSnapshot => {
    const items = list();
    return {
      projects: Object.fromEntries(items.map((project) => [project.id, project])),
    };
  };

  const getSnapshotPatch = (): JsonPatchOperation[] => [
    {
      op: "add",
      path: "/projects",
      value: getSnapshot().projects,
    },
  ];

  const subscribe = (listener: (patches: JsonPatchOperation[]) => void) => {
    listeners.add(listener);
    return () => listeners.delete(listener);
  };

  const create = (input: { name: string }) => {
    const timestamp = nowTimestamp();
    const project: ProjectRecord = {
      id: crypto.randomUUID(),
      name: input.name,
      created_at: timestamp,
      updated_at: timestamp,
    };

    db.insert(projects).values(project).run();
    db.insert(ticket_statuses)
      .values(
        DEFAULT_TICKET_STATUSES.map((status, index) => ({
          id: crypto.randomUUID(),
          project_id: project.id,
          name: status.name,
          color: status.color,
          sort_order: index + 1,
          is_default: status.is_default,
