import { and, eq } from "drizzle-orm";
import type { DbClient } from "../db/connection";
import { ticket_statuses, tickets } from "../db/schema";

const nowTimestamp = () => new Date().toISOString();

const TICKET_STATUS_COLORS = ["gray", "blue", "cyan", "green", "yellow", "orange", "red", "purple", "pink"] as const;

const isAllowedTicketStatusColor = (color: string) =>
  TICKET_STATUS_COLORS.includes(color as (typeof TICKET_STATUS_COLORS)[number]);

const assertValidTicketStatusColor = (color: string) => {
  if (!isAllowedTicketStatusColor(color)) {
    throw new Error(`Ticket status color must be one of: ${TICKET_STATUS_COLORS.join(", ")}.`);
  }
};

const normalizeTicketStatusName = (name: string) =>
  name
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, "_");

const assertValidTicketStatusName = (name: string) => {
  if (!/^[a-z0-9]+(?:_[a-z0-9]+)*$/.test(name)) {
    throw new Error("Ticket status name must use snake_case (lowercase letters, digits, and underscores).");
  }
};

export type TicketStatusRemovalResult =
  | { ok: true; reassignedTo: string }
  | { ok: false; reason: "not_found" | "last_status" };

export const createTicketStatusesService = (db: DbClient) => {
  const list = (projectId: string) =>
    db
      .select()
      .from(ticket_statuses)
      .where(eq(ticket_statuses.project_id, projectId))
      .orderBy(ticket_statuses.sort_order)
      .all();

  const get = (projectId: string, statusId: string) => {
    const status = db
      .select()
      .from(ticket_statuses)
      .where(and(eq(ticket_statuses.project_id, projectId), eq(ticket_statuses.id, statusId)))
      .get();

    return status ?? null;
  };

  const create = (
    projectId: string,
    input: {
      name: string;
      color: string;
      sort_order: number;
      is_default: number;
      is_open?: number;
      can_drag_out: number;
      can_drag_in: number;
      can_create: number;
      can_attempt_on_drop: number;
    },
  ) => {
    assertValidTicketStatusColor(input.color);
    const normalizedName = normalizeTicketStatusName(input.name);
    assertValidTicketStatusName(normalizedName);
    const timestamp = nowTimestamp();
    const status = {
      id: crypto.randomUUID(),
      project_id: projectId,
      name: normalizedName,
      color: input.color,
      sort_order: input.sort_order,
      is_default: input.is_default,
      is_open: input.is_open ?? 1,
      can_drag_out: input.can_drag_out,
      can_drag_in: input.can_drag_in,
      can_create: input.can_create,
      can_attempt_on_drop: input.can_attempt_on_drop,
      created_at: timestamp,
      updated_at: timestamp,
    };

    db.insert(ticket_statuses).values(status).run();

    return status;
  };

  const update = (
    projectId: string,
    statusId: string,
    input: {
      name: string;
      color: string;
      sort_order: number;
      is_default: number;
      is_open?: number;
      can_drag_out: number;
      can_drag_in: number;
      can_create: number;
      can_attempt_on_drop: number;
    },
  ) => {
    const existing = get(projectId, statusId);

    if (!existing) return null;

    assertValidTicketStatusColor(input.color);
    const normalizedName = normalizeTicketStatusName(input.name);
    assertValidTicketStatusName(normalizedName);
    const updated = {
      ...existing,
      name: normalizedName,
      color: input.color,
      sort_order: input.sort_order,
      is_default: input.is_default,
      is_open: input.is_open ?? existing.is_open,
      can_drag_out: input.can_drag_out,
      can_drag_in: input.can_drag_in,
      can_create: input.can_create,
      can_attempt_on_drop: input.can_attempt_on_drop,
      updated_at: nowTimestamp(),
    };

    db.update(ticket_statuses)
      .set({
        name: updated.name,
        color: updated.color,
        sort_order: updated.sort_order,
        is_default: updated.is_default,
        is_open: updated.is_open,
        can_drag_out: updated.can_drag_out,
        can_drag_in: updated.can_drag_in,
        can_create: updated.can_create,
        can_attempt_on_drop: updated.can_attempt_on_drop,
        updated_at: updated.updated_at,
      })
      .where(and(eq(ticket_statuses.project_id, projectId), eq(ticket_statuses.id, statusId)))
      .run();

    return updated;
  };

  const remove = (projectId: string, statusId: string): TicketStatusRemovalResult => {
    const statuses = list(projectId);
    const existing = statuses.find((status) => status.id === statusId);

    if (!existing) return { ok: false, reason: "not_found" };
    if (statuses.length <= 1) return { ok: false, reason: "last_status" };

    const remaining = statuses.filter((status) => status.id !== statusId);
    const defaultStatus = remaining.find((status) => status.is_default === 1) ?? remaining[0];

    if (!defaultStatus) {
      return { ok: false, reason: "last_status" };
    }

    if (!remaining.some((status) => status.is_default === 1)) {
      db.update(ticket_statuses).set({ is_default: 0 }).where(eq(ticket_statuses.project_id, projectId)).run();

      db.update(ticket_statuses)
        .set({ is_default: 1, updated_at: nowTimestamp() })
        .where(eq(ticket_statuses.id, defaultStatus.id))
        .run();
    }

    db.update(tickets)
      .set({ status_id: defaultStatus.id, updated_at: nowTimestamp() })
      .where(eq(tickets.status_id, statusId))
      .run();

    db.delete(ticket_statuses)
      .where(and(eq(ticket_statuses.project_id, projectId), eq(ticket_statuses.id, statusId)))
      .run();

    return { ok: true, reassignedTo: defaultStatus.id };
  };

  return { list, get, create, update, remove };
};

